import type { VisaItem, CountryVisas } from './fullVisaDatabase';

function getSwedenMicroDetails(code: string, cat: string, name: string) {
  let fundsMin = "Sweden C Short Stay Tourist / Business Visas require proof of min SEK 450/day (approx EUR 40/day) + confirmed accommodation + return flight + travel medical insurance (min EUR 30,000).";
  let fundsBankMonths = "Last 3 to 6 months personal bank statements stamped by bank branch, showing liquid funds.";
  let fundsSudden = "❌ Sudden 1-day cash deposits right before visa submission at VFS Global / Swedish Embassy are strictly flagged by Migrationsverket. Average balance must be maintained over 3-6 months.";
  let fundsEx = "✅ Sahi: Seasoned 3-6 month bank statement with SEK 450/day liquid equivalent. ❌ Galat: Borrowed lump sum deposited 24 hours prior to appointment.";

  let itrYears = "Income Tax Returns (ITR) or Tax Assessment for the past 2-3 years.";
  let itrMatch = "Reported tax income must reconcile with personal bank credits and employment contract.";
  let itrNoItr = "Not required for short-term visitors fully sponsored by Swedish host or students sponsored by parents.";

  let bankMonths = "Last 3-6 months bank statements.";
  let bankReg = "Regular salary credits or corporate revenue.";
  let bankFd = "Fixed deposits accepted as supporting proof.";
  let bankSource = "Salary, business revenue, or verified sponsor funds.";

  const lowerCode = code.toLowerCase();
  if (cat === 'work' || lowerCode.includes('wrk') || lowerCode.includes('arbetstillst%c3%a5nd') || lowerCode.includes('blue-card')) {
    fundsMin = "Sweden Work Permit (Arbetstillstånd) requires a valid job offer from a Swedish employer + trade union opinion statement + gross monthly salary meeting national threshold (min SEK 27,500/month or SEK 59,500/month for EU Blue Card) + occupational insurance.";
    fundsBankMonths = "Swedish employer job offer, trade union statement, and 3-6 months bank statements.";
    fundsSudden = "Employment contract must specify gross monthly salary in SEK, job title, and Bolagsverket registration.";
    fundsEx = "✅ Sahi: Official job offer + trade union statement + SEK 27,500+/month salary + 6M statements. ❌ Galat: Salary below threshold or missing trade union statement.";
  } else if (cat === 'student' || lowerCode.includes('stu') || lowerCode.includes('residence-permit')) {
    fundsMin = "Sweden Student Residence Permit requires official university acceptance letter from a Swedish higher education institution + tuition fee receipt + proof of living funds of at least SEK 10,314/month for 10 months per academic year (SEK 103,140/year).";
    fundsBankMonths = "3-6 months bank statements in student's name showing min SEK 103,140 liquid balance.";
    fundsSudden = "Bank account must be in the student's name (or joint with parent) with clear source of funds.";
    fundsEx = "✅ Sahi: University acceptance letter + tuition receipt + SEK 103,140 in student's bank account. ❌ Galat: Bank account in third-party name or unverified funding.";
  } else if (cat === 'family' || lowerCode.includes('fam') || lowerCode.includes('reunification') || lowerCode.includes('sambo')) {
    fundsMin = "Sweden Family Reunification / Sambo Residence Permit requires host in Sweden to meet maintenance requirement (income + adequate housing size) + Inbjudan Form 241011 + Personbevis from Skatteverket + apostilled marriage / cohabitation proof.";
    fundsBankMonths = "6 months bank statements and salary slips of sponsor in Sweden.";
    fundsSudden = "Personbevis (population registration certificate) and Form 241011 required for family/host sponsorship.";
    fundsEx = "✅ Sahi: Inbjudan Form 241011 + Personbevis + sponsor salary proof + housing lease. ❌ Galat: Missing Personbevis or insufficient housing.";
  } else if (cat === 'business' || lowerCode.includes('biz') || lowerCode.includes('entrepreneur')) {
    fundsMin = "Sweden C Business Visa / Self-Employed Permit requires an official invitation letter from a company registered in Sweden with Bolagsverket + home employer dispatch letter + for self-employed, investment capital of min SEK 200,000.";
    fundsBankMonths = "3-6 months corporate and personal bank statements.";
    fundsSudden = "Sponsoring Swedish company must be active in Bolagsverket commercial registry.";
    fundsEx = "✅ Sahi: Official invitation on Swedish firm letterhead + Bolagsverket registration + SEK 200k startup proof. ❌ Galat: Unregistered Swedish firm.";
  } else if (cat === 'pr' || lowerCode.includes('pr') || lowerCode.includes('put') || lowerCode.includes('spe')) {
    fundsMin = "Sweden Permanent Residence (PUT) requires 4 years continuous legal residence on work permit / 5 years for EU Long-Term Residence + Swedish language proficiency + financial self-sufficiency + clean background check.";
    fundsBankMonths = "4-5 years employment history, tax notices, and bank statements.";
    fundsSudden = "Continuous residence history evaluated by Migrationsverket.";
    fundsEx = "✅ Sahi: 4 years work permit history + tax compliance + Swedish language proof. ❌ Galat: Gap in legal stay or tax non-compliance.";
  }

  return {
    fundsBox: { minimum: fundsMin, bankMonths: fundsBankMonths, suddenDeposit: fundsSudden, example: fundsEx },
    itrBox: { years: itrYears, match: itrMatch, noItr: itrNoItr },
    bankBox: { months: bankMonths, regularCredit: bankReg, fd: bankFd, source: bankSource }
  };
}

