function convertRawToVisaItem(item: RawSwedenItem): VisaItem {
  const docList = item.docs ? item.docs.split(' + ') : [];
  const details = getSwedenMicroDetails(item.id, item.category, item.name);

  return {
    id: item.id,
    name: item.name,
    officialCode: item.officialCode,
    categoryCode: item.category,
    fee: item.fee,
    validity: item.validity,
    stay: item.validity,
    purpose: `Official ${item.category} visa and residence permit entry for Sweden (Migrationsverket).`,
    eligibility: "Valid passport with min 3 months validity, 2 blank pages, travel medical insurance EUR 30,000, confirmed travel itinerary / Swedish employer contract / university admission, and financial proof.",
    popular: item.id === 'se-TOU-001' || item.id === 'se-BIZ-001' || item.id === 'se-WRK-001' || item.id === 'se-STU-001' || item.id === 'se-FAM-001' || item.id === 'se-PR-001',
    highlight: item.id === 'se-TOU-001' || item.id === 'se-WRK-001' || item.id === 'se-STU-001',
    record_type: item.record_type,
    toCountry: item.toCountry,
    fromCountry: item.fromCountry,
    warningBox: item.warningBox,
    rawFundsBox: item.fundsBox,
    rawBankBox: item.bankBox,
    docs: docList,
    fundsBox: details.fundsBox,
    itrBox: details.itrBox,
    bankBox: details.bankBox
  };
}

export const SWEDEN_94_VISAS: CountryVisas = {
  tourist: RAW_SE_ITEMS.filter(i => i.category === 'tourist').map(convertRawToVisaItem),
  business: RAW_SE_ITEMS.filter(i => i.category === 'business').map(convertRawToVisaItem),
  work: RAW_SE_ITEMS.filter(i => i.category === 'work').map(convertRawToVisaItem),
  student: RAW_SE_ITEMS.filter(i => i.category === 'student').map(convertRawToVisaItem),
  family: RAW_SE_ITEMS.filter(i => i.category === 'family').map(convertRawToVisaItem),
  pr: RAW_SE_ITEMS.filter(i => i.category === 'pr').map(convertRawToVisaItem)
};
